11	 */
12	public final class BaggageDtos {
13	
14	    private BaggageDtos() {
15	    }
16	
17	    /** 登记航段请求。 */
18	    public record RegisterLegRequest(
19	            @NotBlank(message = "requestId 不能为空") String requestId,
20	            @NotBlank(message = "legId 不能为空") String legId,
21	            @NotBlank(message = "origin 不能为空") String origin,
22	            @NotBlank(message = "destination 不能为空") String destination) {
23	    }
24	
25	    /** 登记行李请求：legIds 为 1~5 个有序航段。 */
26	    public record RegisterBagRequest(
27	            @NotBlank(message = "requestId 不能为空") String requestId,
28	            @NotBlank(message = "bagTag 不能为空") String bagTag,
29	            @NotNull(message = "legIds 不能为空")
30	            @Size(min = 1, max = 5, message = "行程航段数必须为 1~5") List<@NotBlank(message = "航段不能为空") String> legIds) {
31	    }
32	
33	    /** 批量装载请求：1~20 个不重复 bagTag。 */
34	    public record LoadRequest(
35	            @NotBlank(message = "requestId 不能为空") String requestId,
