                                      String departureTime) throws Exception {
        return postJson("/api/legs", Map.of("requestId", UUID.randomUUID().toString(),
                "legId", legId, "origin", origin, "destination", destination,
                "departureTime", departureTime == null ? "" : departureTime));
    }

